pragma solidity 0.8.11;
contract StableArithmeticTest {
    bool public stable = true;
    uint public decimals0 = 1e6;
    uint public decimals1 = 1e18;
    function _k(uint x, uint y) public view returns (uint) {
        if (stable) {
            uint _x = x * 1e18 / decimals0;
            uint _y = y * 1e18 / decimals1;
            uint _a = (_x * _y) / 1e18;
            uint _b = ((_x * _x) / 1e18 + (_y * _y) / 1e18);
            return _a * _b / 1e18;  // x3y+y3x >= k
        } else {
            return x * y; // xy >= k
        }
    }
    function testFuzz_polynomial(uint32 rawX, uint32 rawY) public view {
        uint p = uint(rawX) % 1000000 + 1;
        uint q = uint(rawY) % 1000000 + 1;
        uint observed = _k(p * 1e3, q * 1e15);
        uint referenceValue = (p*p*p*q + p*q*q*q) * 1e6;
        require(referenceValue == observed, "polynomial disagreement");
        require(observed == _k(q * 1e3, p * 1e15), "reserve symmetry");
        require(_k((p+1) * 1e3, q * 1e15) >= observed, "monotonicity");
    }
}

