pragma solidity 0.8.11;
contract StableRoundingTest {
    bool public stable = true;
    uint public decimals0 = 1e6;
    uint public decimals1 = 1e18;
    function _k(uint x, uint y) public view returns (uint) {
        if (stable) {
            uint _x = x * 1e18 / decimals0;
            uint _y = y * 1e18 / decimals1;
            uint _a = (_x * _y) / 1e18;
            uint _b = ((_x * _x) / 1e18 + (_y * _y) / 1e18);
            return _a * _b / 1e18;  // x3y+y3x >= k
        } else {
            return x * y; // xy >= k
        }
    }
    function testFuzz_rounding(uint64 seedX, uint64 seedY) public view {
        uint x = uint(seedX) % 1e6 + 1;
        uint y = uint(seedY) % 1e18 + 1;
        uint a = x * 1e12;
        uint exactFloor = a*y*(a*a+y*y)/1e54;
        uint actual = _k(x,y);
        require(actual <= exactFloor && exactFloor-actual <= 4, "rounding bound");
        require(_k(x+1,y) >= actual && _k(x,y+1) >= actual, "monotonicity");
    }
}
